css:
.section_arc{position:relative}
.ab_arc{position:relative;padding-top:clamp(28px,4vw,48px);padding-bottom:clamp(64px,9vw,120px)}
.ab_arc_bar{position:sticky;top:12px;z-index:40;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;grid-row-gap:12px;grid-column-gap:20px;margin-bottom:28px;padding-top:10px;padding-right:10px;padding-bottom:10px;padding-left:18px;border-top-width:1px;border-top-style:solid;border-top-color:transparent;border-right-width:1px;border-right-style:solid;border-right-color:transparent;border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:transparent;border-left-width:1px;border-left-style:solid;border-left-color:transparent;transition:transform 450ms cubic-bezier(.2,.9,.2,1),background-color 300ms ease,border-color 300ms ease}
.ab_arc_filters{display:flex;flex-wrap:wrap;grid-row-gap:6px;grid-column-gap:6px}
.ab_arc_chip-list{display:contents}
.ab_arc_chip{display:inline-flex;align-items:center;grid-row-gap:8px;grid-column-gap:8px;padding-top:8px;padding-right:12px;padding-bottom:8px;padding-left:12px;border-top-width:1px;border-top-style:solid;border-top-color:var(--_color---neutral--hair);border-right-width:1px;border-right-style:solid;border-right-color:var(--_color---neutral--hair);border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--_color---neutral--hair);border-left-width:1px;border-left-style:solid;border-left-color:var(--_color---neutral--hair);background-color:transparent;font-size:11.5px;line-height:1.2;letter-spacing:0.06em;text-transform:uppercase;color:var(--_color---text--tertiary);cursor:pointer;transition:color 200ms ease,border-color 200ms ease,background-color 200ms ease}
.ab_arc_chip:hover{color:var(--_color---text--primary);border-top-color:var(--_color---neutral--hair-strong);border-right-color:var(--_color---neutral--hair-strong);border-bottom-color:var(--_color---neutral--hair-strong);border-left-color:var(--_color---neutral--hair-strong)}
.ab_arc_chip-count{padding-top:1px;padding-right:5px;padding-bottom:1px;padding-left:5px;background-color:var(--_color---neutral--hair);color:var(--_color---text--primary);font-size:10px;font-weight:500}
.ab_arc_right{display:flex;align-items:center;grid-row-gap:14px;grid-column-gap:14px}
.ab_arc_count{color:var(--_color---text--tertiary);white-space:nowrap}
.ab_switch{position:relative;display:inline-flex;border-top-width:1px;border-top-style:solid;border-top-color:var(--_color---neutral--hair-strong);border-right-width:1px;border-right-style:solid;border-right-color:var(--_color---neutral--hair-strong);border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--_color---neutral--hair-strong);border-left-width:1px;border-left-style:solid;border-left-color:var(--_color---neutral--hair-strong);background-color:rgba(7,8,13,0.6)}
.ab_switch_ind{position:absolute;top:0;bottom:0;left:0;background-color:var(--_color---brand--signal);transition:transform 450ms cubic-bezier(.7,0,.2,1),width 450ms cubic-bezier(.7,0,.2,1)}
.ab_switch_btn{position:relative;z-index:1;padding-top:9px;padding-right:14px;padding-bottom:9px;padding-left:14px;border-top-style:none;border-right-style:none;border-bottom-style:none;border-left-style:none;background-color:transparent;font-size:12px;line-height:1.2;letter-spacing:0.06em;text-transform:uppercase;color:var(--_color---text--tertiary);cursor:pointer;transition:color 300ms ease}
.ab_arc_grid-wrap{position:relative;z-index:3}
.ab_arc_grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));grid-row-gap:20px;grid-column-gap:20px;position:relative;isolation:isolate}
.ab_arc_list{position:relative;z-index:3;isolation:isolate;border-top-width:1px;border-top-style:solid;border-top-color:var(--_color---neutral--hair)}
.ab_arc_peek{position:absolute;left:0;top:0;z-index:30;width:300px;pointer-events:none;opacity:0;border-top-width:1px;border-top-style:solid;border-top-color:var(--_color---neutral--hair-strong);border-right-width:1px;border-right-style:solid;border-right-color:var(--_color---neutral--hair-strong);border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--_color---neutral--hair-strong);border-left-width:1px;border-left-style:solid;border-left-color:var(--_color---neutral--hair-strong);background-color:var(--_color---neutral--panel);transition:opacity 250ms ease}
.ab_arc_empty{padding-top:60px;padding-bottom:60px;text-align:center;color:var(--_color---text--tertiary)}
@media screen and (max-width: 991px) {
.ab_arc_grid{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media screen and (max-width: 767px) {
.ab_arc_grid{grid-template-columns:minmax(0,1fr)}
.ab_arc_filters{flex-wrap:nowrap;overflow-x:auto;margin-left:-16px;margin-right:-16px;padding-left:16px;padding-right:16px;max-width:calc(100% + 32px)}
.ab_arc_chip{white-space:nowrap}
.ab_arc_right{width:100%;justify-content:space-between}
}
